INSERT INTO `upload_rule_template` (`id`, `tenant_id`, `template_code`, `template_name`, `category_group`, `field_schema_json`, `file_requirement_json`, `rule_json`, `tip_text`, `check_mode`, `enabled`, `sort_order`, `remark`, `create_dept`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`) VALUES (18201,'000000','tpl_art_performance','艺术表演节目上传规则包','艺术表演节目','[{\"fieldKey\":\"groupName\",\"fieldLabel\":\"组别\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"甲组\",\"乙组\",\"高校组\",\"中小学组\"]\",\"sortOrder\":1},{\"fieldKey\":\"projectType\",\"fieldLabel\":\"项目类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"声乐\",\"器乐\",\"舞蹈\",\"戏剧\",\"朗诵\"]\",\"sortOrder\":2},{\"fieldKey\":\"programForm\",\"fieldLabel\":\"节目形式\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"独唱\",\"重唱\",\"合唱\",\"独奏\",\"合奏\",\"群舞\",\"小品\",\"戏曲\",\"朗诵\"]\",\"sortOrder\":3},{\"fieldKey\":\"projectNature\",\"fieldLabel\":\"项目性质\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"个人\",\"集体\"]\",\"sortOrder\":4},{\"fieldKey\":\"performanceOrder\",\"fieldLabel\":\"展演顺序\",\"fieldType\":\"input\",\"required\":false,\"validationJson\":\"{\"type\":\"number\"}\",\"sortOrder\":5},{\"fieldKey\":\"original_commitment\",\"fieldLabel\":\"原创承诺\",\"fieldType\":\"checkbox\",\"required\":true,\"optionsJson\":\"[\"已确认原创或具备授权\"]\",\"sortOrder\":6},{\"fieldKey\":\"authorization_commitment\",\"fieldLabel\":\"授权承诺\",\"fieldType\":\"checkbox\",\"required\":true,\"optionsJson\":\"[\"已获得展演传播所需授权\"]\",\"sortOrder\":7},{\"fieldKey\":\"no_identity_in_video\",\"fieldLabel\":\"视频无身份信息确认\",\"fieldType\":\"checkbox\",\"required\":true,\"optionsJson\":\"[\"视频中不出现省份、学校、姓名、指导教师姓名\"]\",\"sortOrder\":8}]','[{\"fileTypeCode\":\"video\",\"fileTypeName\":\"节目视频\",\"allowedExt\":\"mp4,mov\",\"maxSizeMb\":1024,\"minCount\":1,\"maxCount\":1,\"required\":true,\"ruleJson\":\"{\"mediaType\":\"video\",\"maxMb\":1024,\"minWidth\":1920,\"minHeight\":1080,\"fps\":25,\"fpsTolerance\":0.5,\"minBitrateMbps\":10,\"minDurationSeconds\":30,\"maxDurationSeconds\":480,\"manualCheckTips\":[\"视频中不得出现省份、学校、姓名、指导教师姓名。\",\"核验原创或授权承诺。\"]}\",\"sortOrder\":1},{\"fileTypeCode\":\"document\",\"fileTypeName\":\"节目申报材料\",\"allowedExt\":\"doc,docx,pdf\",\"maxSizeMb\":50,\"minCount\":0,\"maxCount\":2,\"required\":false,\"ruleJson\":\"{\"maxMb\":50,\"filenamePattern\":\"(?i).*(申报|报名|program|application).*\",\"manualCheckTips\":[\"申报材料需与系统字段、成员名单保持一致。\"]}\",\"sortOrder\":2}]','{\"validatorType\":\"performance\",\"fps\":25,\"fpsTolerance\":0.5,\"minBitrateMbps\":10,\"maxDurationSecondsByProjectNature\":{\"个人\":300,\"集体\":480,\"individual\":300,\"collective\":480},\"manualCheckTips\":[\"视频中不得出现省份、学校、姓名、指导教师姓名。\",\"系统仅校验承诺勾选，原创/授权真实性需人工复核。\"],\"rejectReasonTemplates\":[\"视频技术参数不符合要求。\",\"视频出现学校或人员身份信息。\",\"原创或授权承诺材料不足。\"]}','请上传 MP4/MOV 节目视频，系统将校验分辨率、帧率、码率、时长和大小；视频身份信息、原创授权由承诺与人工审核结合判断。','mixed',1,10,'系统预置模板',103,1,'2026-06-13 17:20:08',NULL,'2026-06-20 12:09:19','0'),
(18202,'000000','tpl_art_work','艺术作品上传规则包','艺术作品','[{\"fieldKey\":\"groupName\",\"fieldLabel\":\"组别\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"甲组\",\"乙组\",\"高校组\",\"中小学组\"]\",\"sortOrder\":1},{\"fieldKey\":\"projectType\",\"fieldLabel\":\"项目类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"绘画\",\"书法\",\"篆刻\",\"摄影\",\"设计\",\"微电影\",\"短视频\",\"AIGC动画\"]\",\"sortOrder\":2},{\"fieldKey\":\"programForm\",\"fieldLabel\":\"作品形式\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"普通作品\",\"纪录短片\",\"剧情短片\",\"AIGC动画短片\"]\",\"sortOrder\":3},{\"fieldKey\":\"work_type\",\"fieldLabel\":\"作品类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"普通作品\",\"纪录短片\",\"剧情短片\",\"AIGC动画短片\"]\",\"sortOrder\":4},{\"fieldKey\":\"work_size\",\"fieldLabel\":\"作品尺寸/规格\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":5},{\"fieldKey\":\"creation_description\",\"fieldLabel\":\"创作说明\",\"fieldType\":\"textarea\",\"required\":true,\"validationJson\":\"{\"maxLength\":400}\",\"sortOrder\":6},{\"fieldKey\":\"ai_usage_ratio\",\"fieldLabel\":\"AI工具使用比例\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":7},{\"fieldKey\":\"ai_process_description\",\"fieldLabel\":\"AI创作流程简述\",\"fieldType\":\"textarea\",\"required\":false,\"sortOrder\":8},{\"fieldKey\":\"original_commitment\",\"fieldLabel\":\"原创承诺\",\"fieldType\":\"checkbox\",\"required\":true,\"optionsJson\":\"[\"本人承诺作品原创或已获得合法授权\"]\",\"sortOrder\":9}]','[{\"fileTypeCode\":\"image\",\"fileTypeName\":\"非影视作品图片\",\"allowedExt\":\"jpg,jpeg\",\"maxSizeMb\":100,\"minCount\":1,\"maxCount\":5,\"required\":false,\"ruleJson\":\"{\"mediaType\":\"image\",\"minMb\":5,\"maxMb\":100,\"dpi\":300,\"manualCheckTips\":[\"DPI缺失时需人工确认是否达到300dpi。\",\"图片需能清晰呈现作品整体和细节。\"]}\",\"sortOrder\":1},{\"fileTypeCode\":\"video\",\"fileTypeName\":\"影视作品视频\",\"allowedExt\":\"mp4,mov\",\"maxSizeMb\":1024,\"minCount\":0,\"maxCount\":1,\"required\":false,\"ruleJson\":\"{\"mediaType\":\"video\",\"maxMb\":1024,\"minBitrateMbps\":10,\"minDurationSeconds\":30,\"maxDurationSeconds\":480,\"manualCheckTips\":[\"短片类别、时长和AIGC说明需人工复核。\"]}\",\"sortOrder\":2},{\"fileTypeCode\":\"document\",\"fileTypeName\":\"作品说明或授权材料\",\"allowedExt\":\"doc,docx,pdf\",\"maxSizeMb\":50,\"minCount\":0,\"maxCount\":2,\"required\":false,\"ruleJson\":\"{\"maxMb\":50,\"manualCheckTips\":[\"授权、创作说明、AIGC过程材料需与申报字段一致。\"]}\",\"sortOrder\":3}]','{\"validatorType\":\"artwork\",\"filmVideoRules\":{\"纪录短片\":{\"maxDurationSeconds\":480,\"minBitrateMbps\":10},\"剧情短片\":{\"maxDurationSeconds\":480,\"minBitrateMbps\":10},\"AIGC动画短片\":{\"maxDurationSeconds\":300,\"minBitrateMbps\":10},\"documentary\":{\"maxDurationSeconds\":480,\"minBitrateMbps\":10},\"feature\":{\"maxDurationSeconds\":480,\"minBitrateMbps\":10},\"aigc\":{\"maxDurationSeconds\":300,\"minBitrateMbps\":10}},\"manualCheckTips\":[\"普通作品作者不超过3人，影视作者不超过6人。\",\"AIGC动画短片需核验AI工具使用比例和创作流程。\"],\"rejectReasonTemplates\":[\"作品图片格式、大小或DPI不符合要求。\",\"作者或指导教师人数超限。\",\"AIGC创作过程说明不完整。\"]}','非影视作品请上传 JPG/JPEG 图片；影视类按短片类别上传视频，时长和码率可通过 filmVideoRules 调整。','mixed',1,20,'系统预置模板',103,1,'2026-06-13 17:20:08',NULL,'2026-06-20 12:09:19','0'),
(18203,'000000','tpl_workshop','艺术实践工作坊上传规则包','艺术实践工作坊','[{\"fieldKey\":\"groupName\",\"fieldLabel\":\"组别\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"高校组\",\"中小学组\"]\",\"sortOrder\":1},{\"fieldKey\":\"projectType\",\"fieldLabel\":\"项目类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"艺术实践工作坊\"]\",\"sortOrder\":2},{\"fieldKey\":\"programForm\",\"fieldLabel\":\"工作坊形式\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"美术工作坊\",\"设计工作坊\",\"音乐工作坊\",\"舞蹈工作坊\",\"戏剧工作坊\",\"综合实践工作坊\"]\",\"sortOrder\":3},{\"fieldKey\":\"project_intro\",\"fieldLabel\":\"项目简介\",\"fieldType\":\"textarea\",\"required\":true,\"sortOrder\":4},{\"fieldKey\":\"design_idea\",\"fieldLabel\":\"设计思路\",\"fieldType\":\"textarea\",\"required\":true,\"sortOrder\":5},{\"fieldKey\":\"feature_desc\",\"fieldLabel\":\"特色描述\",\"fieldType\":\"textarea\",\"required\":true,\"sortOrder\":6},{\"fieldKey\":\"exhibition_design_plan\",\"fieldLabel\":\"展区设计方案\",\"fieldType\":\"textarea\",\"required\":true,\"sortOrder\":7},{\"fieldKey\":\"no_previous_award_commitment\",\"fieldLabel\":\"未获奖工作坊确认\",\"fieldType\":\"checkbox\",\"required\":true,\"optionsJson\":\"[\"确认不是历届已获奖工作坊\"]\",\"sortOrder\":8}]','[{\"fileTypeCode\":\"video\",\"fileTypeName\":\"工作坊视频\",\"allowedExt\":\"mp4,mpg,mpeg\",\"maxSizeMb\":1024,\"minCount\":1,\"maxCount\":1,\"required\":true,\"ruleJson\":\"{\"mediaType\":\"video\",\"maxMb\":1024,\"minDurationSeconds\":60,\"maxDurationSeconds\":480,\"manualCheckTips\":[\"核验工作坊不是历届已获奖工作坊。\",\"视频需呈现工作坊实施过程和成果。\"]}\",\"sortOrder\":1},{\"fileTypeCode\":\"document\",\"fileTypeName\":\"工作坊方案\",\"allowedExt\":\"doc,docx,pdf\",\"maxSizeMb\":100,\"minCount\":1,\"maxCount\":1,\"required\":true,\"ruleJson\":\"{\"maxMb\":100,\"filenamePattern\":\"(?i).*(方案|plan|workshop).*\",\"manualCheckTips\":[\"方案需包含项目简介、设计思路、特色描述和展区设计。\"]}\",\"sortOrder\":2},{\"fileTypeCode\":\"archive\",\"fileTypeName\":\"支撑材料压缩包\",\"allowedExt\":\"zip,rar,7z\",\"maxSizeMb\":500,\"minCount\":0,\"maxCount\":1,\"required\":false,\"ruleJson\":\"{\"maxMb\":500,\"manualCheckTips\":[\"压缩包仅作为辅助佐证材料，需人工确认目录和内容。\"]}\",\"sortOrder\":3}]','{\"validatorType\":\"workshop\",\"minStudentCount\":7,\"maxStudentCount\":9,\"minTeacherCount\":1,\"maxTeacherCount\":3,\"maxTotalMemberCount\":12,\"maxVideoDurationSeconds\":480,\"canonicalFieldKeys\":{\"groupName\":[\"groupName\"],\"projectType\":[\"projectType\"],\"programForm\":[\"programForm\"]},\"memberFieldGroups\":{\"participant\":[{\"fieldKey\":\"name\",\"fieldLabel\":\"姓名\",\"fieldType\":\"input\",\"required\":true,\"sortOrder\":1},{\"fieldKey\":\"studentNo\",\"fieldLabel\":\"学号\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":2},{\"fieldKey\":\"department\",\"fieldLabel\":\"院系\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":3},{\"fieldKey\":\"major\",\"fieldLabel\":\"专业\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":4},{\"fieldKey\":\"roleName\",\"fieldLabel\":\"成员角色\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"学生\",\"指导教师\",\"负责人\"]\",\"sortOrder\":5}]},\"manualCheckTips\":[\"学生7-9人、指导教师1-3人，总人数不超过12人。\",\"一校一队一坊，历届已获奖工作坊不得重复申报。\",\"展区设计方案和视频内容需人工核对一致性。\"],\"rejectReasonTemplates\":[\"成员人数不符合工作坊要求。\",\"视频时长或格式不符合要求。\",\"项目简介、设计思路、特色描述或展区设计方案缺失。\",\"工作坊方案或支撑材料与填报信息不一致。\"]}','请维护学生和指导教师成员列表，填写工作坊形式、项目简介、设计思路、特色描述和展区设计方案，并上传不超过8分钟的工作坊视频。','mixed',1,30,'系统预置模板',103,1,'2026-06-13 17:20:08',NULL,'2026-06-20 12:09:19','0'),
(18204,'000000','tpl_reform_result','高校美育改革创新成果上传规则包','高校美育改革创新成果','[{\"fieldKey\":\"groupName\",\"fieldLabel\":\"组别\",\"fieldType\":\"select\",\"required\":false,\"optionsJson\":\"[\"高校组\",\"本科院校\",\"高职高专\"]\",\"sortOrder\":1},{\"fieldKey\":\"projectType\",\"fieldLabel\":\"项目类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"高校美育改革创新成果\"]\",\"sortOrder\":2},{\"fieldKey\":\"programForm\",\"fieldLabel\":\"成果形式\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"学术论文\",\"教学改革案例\"]\",\"sortOrder\":3},{\"fieldKey\":\"achievement_type\",\"fieldLabel\":\"成果类型\",\"fieldType\":\"select\",\"required\":true,\"optionsJson\":\"[\"学术论文\",\"教学改革案例\"]\",\"sortOrder\":4},{\"fieldKey\":\"abstract\",\"fieldLabel\":\"摘要\",\"fieldType\":\"textarea\",\"required\":false,\"sortOrder\":5},{\"fieldKey\":\"keywords\",\"fieldLabel\":\"关键词\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":6},{\"fieldKey\":\"body_text\",\"fieldLabel\":\"正文/案例正文\",\"fieldType\":\"textarea\",\"required\":true,\"sortOrder\":7},{\"fieldKey\":\"references\",\"fieldLabel\":\"参考文献\",\"fieldType\":\"textarea\",\"required\":false,\"sortOrder\":8},{\"fieldKey\":\"unpublished_commitment\",\"fieldLabel\":\"未公开发表承诺\",\"fieldType\":\"checkbox\",\"required\":false,\"optionsJson\":\"[\"承诺未公开发表\"]\",\"sortOrder\":9},{\"fieldKey\":\"unit_name\",\"fieldLabel\":\"提交单位\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":10}]','[{\"fileTypeCode\":\"document\",\"fileTypeName\":\"成果正文或附件\",\"allowedExt\":\"doc,docx,pdf\",\"maxSizeMb\":100,\"minCount\":1,\"maxCount\":3,\"required\":true,\"ruleJson\":\"{\"maxMb\":100,\"filenamePattern\":\"(?i).*(成果|论文|案例|改革|achievement|paper|case).*\",\"manualCheckTips\":[\"正文附件需与系统填写的摘要、关键词、正文和参考文献一致。\"]}\",\"sortOrder\":1},{\"fileTypeCode\":\"video\",\"fileTypeName\":\"案例视频\",\"allowedExt\":\"mp4,mov\",\"maxSizeMb\":1024,\"minCount\":0,\"maxCount\":1,\"required\":false,\"ruleJson\":\"{\"mediaType\":\"video\",\"maxMb\":1024,\"maxDurationSeconds\":300,\"manualCheckTips\":[\"案例视频不超过5分钟，需人工确认内容与案例正文一致。\"]}\",\"sortOrder\":2},{\"fileTypeCode\":\"image\",\"fileTypeName\":\"案例图片\",\"allowedExt\":\"jpg,jpeg\",\"maxSizeMb\":100,\"minCount\":0,\"maxCount\":5,\"required\":false,\"ruleJson\":\"{\"mediaType\":\"image\",\"minMb\":10,\"maxMb\":100,\"dpi\":300,\"manualCheckTips\":[\"DPI缺失时需人工确认是否达到300dpi。\"]}\",\"sortOrder\":3}]','{\"validatorType\":\"aesthetic_achievement\",\"paperMaxAuthorCount\":2,\"paperAbstractMinLength\":250,\"paperAbstractMaxLength\":350,\"paperMinKeywordCount\":3,\"paperMaxKeywordCount\":5,\"paperMinBodyLength\":5000,\"caseMaxCompleterCount\":3,\"caseMaxTextLength\":5000,\"caseMaxVideoCount\":1,\"caseVideoMaxMb\":1024,\"caseVideoMaxDurationSeconds\":300,\"caseMaxImageCount\":5,\"caseImageMinMb\":10,\"caseImageMinDpi\":300,\"canonicalFieldKeys\":{\"groupName\":[\"groupName\"],\"projectType\":[\"projectType\"],\"programForm\":[\"programForm\"]},\"memberFieldGroups\":{\"author\":[{\"fieldKey\":\"name\",\"fieldLabel\":\"作者姓名\",\"fieldType\":\"input\",\"required\":true,\"sortOrder\":1},{\"fieldKey\":\"department\",\"fieldLabel\":\"所在单位/院系\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":2},{\"fieldKey\":\"roleName\",\"fieldLabel\":\"作者排序/贡献\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":3}],\"participant\":[{\"fieldKey\":\"name\",\"fieldLabel\":\"完成人姓名\",\"fieldType\":\"input\",\"required\":true,\"sortOrder\":1},{\"fieldKey\":\"department\",\"fieldLabel\":\"所在单位/院系\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":2},{\"fieldKey\":\"roleName\",\"fieldLabel\":\"完成分工\",\"fieldType\":\"input\",\"required\":false,\"sortOrder\":3}]},\"manualCheckTips\":[\"学术论文需核验未公开发表承诺和参考文献。\",\"教学改革案例需以单位名义提交，并包含背景、做法、成效、建议。\",\"论文作者不超过2人，教学改革案例完成人不超过3人。\"],\"rejectReasonTemplates\":[\"论文摘要、关键词、正文或参考文献不符合要求。\",\"未勾选未公开发表承诺。\",\"教学改革案例结构或附件不符合要求。\",\"作者、完成人、提交单位或成果形式填写不完整。\"]}','学术论文和教学改革案例按成果类型分别校验。请完整填写成果形式、正文、摘要、关键词、参考文献或案例结构，并上传成果正文或附件。','mixed',1,40,'系统预置模板',103,1,'2026-06-13 17:20:08',NULL,'2026